#!/usr/bin/env python3
"""Probe: independent Erdos-Straus representation counter + timing."""
import sys, time

def spf_sieve(N):
    spf = list(range(N + 1))
    i = 2
    while i * i <= N:
        if spf[i] == i:
            for j in range(i * i, N + 1, i):
                if spf[j] == j:
                    spf[j] = i
        i += 1
    return spf

def factor(x, spf):
    f = {}
    while x > 1:
        p = spf[x]
        while x % p == 0:
            f[p] = f.get(p, 0) + 1
            x //= p
    return f

def divisors_from_fact(f):
    divs = [1]
    for p, e in f.items():
        pw = [p ** k for k in range(e + 1)]
        divs = [d * q for d in divs for q in pw]
    return divs

def count_reps(n, spf):
    """# of (x<=y<=z) positive ints with 4/n = 1/x+1/y+1/z."""
    total = 0
    lo = n // 4 + 1
    hi = (3 * n) // 4
    for x in range(lo, hi + 1):
        a = 4 * x - n
        b = n * x
        if a <= 0:
            continue
        # need 1/y+1/z = a/b with x <= y <= z
        # (a y - b)(a z - b) = b^2 ; d = a y - b divisor of b^2, d <= b
        fx = factor(x, spf)
        fb2 = {p: 2 * e for p, e in fx.items()}
        fb2[n] = fb2.get(n, 0) + 2   # n prime, n does not divide x (x<n)
        for d in divisors_from_fact(fb2):
            if d > b:
                continue
            if (b + d) % a:
                continue
            y = (b + d) // a
            if y < x:
                continue
            dp = (b * b) // d
            if (b + dp) % a:
                continue
            total += 1
    return total

if __name__ == "__main__":
    import json
    census = json.load(open("commons/data/agent-011_erdos_straus_prime5000_20260801T184200Z.json"))
    rows = {r["n"]: r["representations"] for r in census["rows"]}
    spf = spf_sieve(4000)
    tests = [5, 7, 11, 13, 23, 97, 101, 1009, 2003, 3001]
    t0 = time.time()
    for n in tests:
        c = count_reps(n, spf)
        print(n, c, rows.get(n), "OK" if c == rows.get(n) else "MISMATCH")
    print("elapsed", round(time.time() - t0, 2))

